    /**
     * Handles loading a Plant using a UUID
     * @param		UUID uuid 
     * @return		Plant
     */    
    @GetMapping("/load")
    public Plant load( @RequestParam(required=true) UUID uuid ) {    	
    	Plant entity = null;

    	try {  
    		entity = service.getPlant( new PlantFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Plant using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Plant business objects
     * @return		Set<Plant>
     */
    @GetMapping("/")
    public List<Plant> loadAll() {                
    	List<Plant> plantList = null;
        
    	try {
            // load the Plant
            plantList = service.getAllPlant();
            
            if ( plantList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Plants" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Plants ", exc );
        	return null;
        }

        return plantList;
                            
    }

